        private static readonly Dictionary<string, Geometry> _cache = new Dictionary<string, Geometry>(StringComparer.Ordinal);

        public static Geometry GetGeometry(string providerId)
        {
            if (providerId == null || !_icons.TryGetValue(providerId, out Icon _icon))
            {
                return null;
            }

            lock (_cache)
            {
                if (!_cache.TryGetValue(providerId, out Geometry _geometry))
                {
                    try
                    {
                        _geometry = Geometry.Parse(_icon.Data);
                        _geometry.Freeze();
                    }
                    catch
                    {
                        _geometry = null;
                    }

                    _cache[providerId] = _geometry;
                }

                return _geometry;
            }
        }

        public static Brush GetBrush(string providerId)
        {
            string _color = null;

            if (providerId != null && _icons.TryGetValue(providerId, out Icon _icon))
            {
                _color = _icon.Color;
            }

            if (_color == null)
            {
                _color = Framework.Settings.Instance.FontColor;
            }

            try
            {
                Brush _brush = (Brush)new BrushConverter().ConvertFromString(_color);
                _brush.Freeze();
                return _brush;
            }
            catch
            {
                return Brushes.White;
            }
        }
    }
